INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_1', 'How’s everything?', 'Nasıl gidiyor?', 'How’s everything at work?', 'A2', 20, 1, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_10', 'I owe you one.', 'Sana bir iyilik borcum var.', 'Thanks! I owe you one.', 'A2', 20, 10, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_11', 'It’s my pleasure.', 'Rica ederim / Memnun oldum.', 'It’s my pleasure to help.', 'A2', 20, 11, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_12', 'Do you have a minute?', 'Bir dakikan var mı?', 'Do you have a minute to talk?', 'A2', 20, 12, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_13', 'Sorry, I didn’t catch that.', 'Üzgünüm, anlayamadım.', 'Sorry, I didn’t catch that. Can you repeat?', 'A2', 20, 13, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_14', 'Could you say that again?', 'Tekrar eder misin?', 'Could you say that again, please?', 'A2', 20, 14, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_15', 'Let me think…', 'Düşüneyim…', 'Let me think about it.', 'A2', 20, 15, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_16', 'Let me check.', 'Kontrol edeyim.', 'Let me check the schedule.', 'A2', 20, 16, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_17', 'Guess what?', 'Bil bakalım ne oldu?', 'Guess what? I got the job!', 'A2', 20, 17, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_18', 'Take care.', 'Kendine iyi bak.', 'Bye! Take care.', 'A2', 20, 18, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_19', 'Same here.', 'Ben de aynı şekilde.', 'I love this place. — Same here.', 'A2', 20, 19, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_2', 'Long time no see!', 'Uzun zamandır görüşemedik!', 'Long time no see, how are you?', 'A2', 20, 2, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_20', 'It depends.', 'Duruma bağlı.', 'Will it rain? — It depends.', 'A2', 20, 20, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_21', 'Can you do me a favor?', 'Bana bir iyilik yapabilir misin?', 'Can you do me a favor later?', 'A2', 20, 21, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_22', 'Can you help me out?', 'Bana yardım eder misin?', 'Can you help me out with this?', 'A2', 20, 22, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_23', 'Would you mind…?', 'Sakıncası var mı?', 'Would you mind opening the window?', 'A2', 20, 23, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_24', 'Is that okay with you?', 'Senin için uygun mu?', 'We meet at 6. Is that okay with you?', 'A2', 20, 24, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_25', 'I’m not sure about that.', 'Bundan emin değilim.', 'I’m not sure about that plan.', 'A2', 20, 25, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_26', 'Let’s give it a try.', 'Hadi bir deneyelim.', 'Let’s give it a try together.', 'A2', 20, 26, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_27', 'Let me show you.', 'Sana göstereyim.', 'Let me show you the way.', 'A2', 20, 27, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_28', 'Feel free to…', 'Çekinmeden…', 'Feel free to ask questions.', 'A2', 20, 28, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_29', 'Go ahead.', 'Devam et / buyur.', 'Can I start? — Go ahead.', 'A2', 20, 29, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_3', 'Nice to see you again.', 'Seni tekrar görmek güzel.', 'Nice to see you again!', 'A2', 20, 3, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_30', 'Don’t worry about it.', 'Dert etme.', 'It’s fine, don’t worry about it.', 'A2', 20, 30, '2026-06-11 13:02:44.778833+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('A2_20_31', 'I didn’t mean to…', 'Amacım… değildi.', 'I didn’t mean to upset you.', 'A2', 20, 31, '2026-06-11 13:02:44.778833+00');
