INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_21_9', 'at a crossroads', 'dönüm noktasında', 'He is at a crossroads in life.', 'B2', 21, 9, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_1', 'It can be argued that', 'Şu savunulabilir ki', 'It can be argued that this policy needs revision.', 'B2', 22, 1, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_10', 'This perspective is based on', 'Bu bakış açısı ... temellidir', 'This perspective is based on empirical data.', 'B2', 22, 10, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_11', 'It could be suggested that', 'Şu önerilebilir ki', 'It could be suggested that alternatives exist.', 'B2', 22, 11, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_12', 'One notable aspect is that', 'Dikkat çekici bir yön şudur ki', 'One notable aspect is that participation increased.', 'B2', 22, 12, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_13', 'There is little doubt that', 'Şu konuda pek şüphe yok ki', 'There is little doubt that education matters.', 'B2', 22, 13, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_14', 'This viewpoint emphasizes the need for', 'Bu görüş, ... ihtiyacını vurgular', 'This viewpoint emphasizes the need for cooperation.', 'B2', 22, 14, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_15', 'It may be reasonable to assume that', 'Şunu varsaymak makul olabilir ki', 'It may be reasonable to assume that costs will rise.', 'B2', 22, 15, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_16', 'This argument is supported by', 'Bu argüman ... tarafından desteklenir', 'This argument is supported by recent studies.', 'B2', 22, 16, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_17', 'In many respects', 'Birçok açıdan', 'In many respects, the system works well.', 'B2', 22, 17, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_18', 'It remains unclear whether', '... olup olmadığı belirsizliğini koruyor', 'It remains unclear whether the plan will succeed.', 'B2', 22, 18, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_19', 'This observation suggests that', 'Bu gözlem, ... olduğunu düşündürür', 'This observation suggests that reform is needed.', 'B2', 22, 19, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_2', 'From a broader perspective', 'Daha geniş bir perspektiften', 'From a broader perspective, the issue affects society.', 'B2', 22, 2, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_20', 'A common criticism is that', 'Yaygın bir eleştiri şudur ki', 'A common criticism is that access is unequal.', 'B2', 22, 20, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_21', 'As a result of this', 'Bunun sonucunda', 'As a result of this, productivity increased.', 'B2', 22, 21, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_22', 'This can largely be attributed to', 'Bu büyük ölçüde ...''ye bağlanabilir', 'This can largely be attributed to policy changes.', 'B2', 22, 22, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_23', 'In contrast to previous findings', 'Önceki bulguların aksine', 'In contrast to previous findings, outcomes improved.', 'B2', 22, 23, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_24', 'This leads to the conclusion that', 'Bu, şu sonuca götürür ki', 'This leads to the conclusion that action is required.', 'B2', 22, 24, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_25', 'Compared with earlier models', 'Önceki modellerle karşılaştırıldığında', 'Compared with earlier models, this system is efficient.', 'B2', 22, 25, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_26', 'This difference stems from', 'Bu fark ...''den kaynaklanır', 'This difference stems from structural changes.', 'B2', 22, 26, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_27', 'As opposed to traditional methods', 'Geleneksel yöntemlerin aksine', 'As opposed to traditional methods, this approach is flexible.', 'B2', 22, 27, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_28', 'This effect is likely due to', 'Bu etki büyük olasılıkla ... nedeniyle', 'This effect is likely due to increased demand.', 'B2', 22, 28, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_29', 'There is a clear distinction between', '... arasında net bir ayrım vardır', 'There is a clear distinction between theory and practice.', 'B2', 22, 29, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_3', 'There is a growing tendency to', '... yönünde artan bir eğilim var', 'There is a growing tendency to work remotely.', 'B2', 22, 3, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_30', 'This outcome depends largely on', 'Bu sonuç büyük ölçüde ...''ye bağlıdır', 'This outcome depends largely on cooperation.', 'B2', 22, 30, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_31', 'Under these circumstances', 'Bu koşullar altında', 'Under these circumstances, delay is inevitable.', 'B2', 22, 31, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_32', 'This contrasts sharply with', 'Bu, ... ile keskin bir tezat oluşturur', 'This contrasts sharply with earlier assumptions.', 'B2', 22, 32, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_33', 'As a consequence of this trend', 'Bu eğilimin bir sonucu olarak', 'As a consequence of this trend, costs rose.', 'B2', 22, 33, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_34', 'This pattern can be observed in', 'Bu örüntü ...''de gözlemlenebilir', 'This pattern can be observed in urban areas.', 'B2', 22, 34, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_35', 'In comparison with similar cases', 'Benzer vakalarla karşılaştırıldığında', 'In comparison with similar cases, results differ.', 'B2', 22, 35, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_36', 'This situation arises when', 'Bu durum ... olduğunda ortaya çıkar', 'This situation arises when demand exceeds supply.', 'B2', 22, 36, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_37', 'The primary reason for this is', 'Bunun temel nedeni şudur:', 'The primary reason for this is lack of funding.', 'B2', 22, 37, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_38', 'This relationship highlights the importance of', 'Bu ilişki, ...''in önemini vurgular', 'This relationship highlights the importance of trust.', 'B2', 22, 38, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_39', 'As long as this condition holds', 'Bu koşul geçerli olduğu sürece', 'As long as this condition holds, stability remains.', 'B2', 22, 39, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_4', 'It is widely assumed that', 'Genel olarak şu varsayılır ki', 'It is widely assumed that technology drives change.', 'B2', 22, 4, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_2_69', 'future-oriented', 'geleceğe yönelik', 'We need a future-oriented plan.', 'B2', 2, 69, '2026-06-11 13:02:44.874361+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_40', 'This outcome is influenced by', 'Bu sonuç ... tarafından etkilenir', 'This outcome is influenced by external factors.', 'B2', 22, 40, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_41', 'In order to achieve this goal', 'Bu hedefe ulaşmak için', 'In order to achieve this goal, cooperation is required.', 'B2', 22, 41, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_42', 'This is intended to', 'Bu, ... amaçlanmıştır', 'This is intended to improve efficiency.', 'B2', 22, 42, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_43', 'There is a strong likelihood that', 'Büyük olasılıkla', 'There is a strong likelihood that demand will grow.', 'B2', 22, 43, '2026-06-11 13:02:44.865252+00');
