INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_45', 'Provided that these conditions are met', 'Bu koşullar sağlandığı takdirde', 'Provided that these conditions are met, success is possible.', 'B2', 22, 45, '2026-06-11 13:02:44.865252+00');
