INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_48', 'This makes it possible to', 'Bu, ... mümkün kılar', 'This makes it possible to expand access.', 'B2', 22, 48, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_49', 'There is a possibility that', '... olasılığı vardır', 'There is a possibility that outcomes may differ.', 'B2', 22, 49, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_5', 'One possible explanation is that', 'Olası bir açıklama şudur ki', 'One possible explanation is that resources are limited.', 'B2', 22, 5, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_50', 'This is necessary in order to', '... için gereklidir', 'This is necessary in order to maintain quality.', 'B2', 22, 50, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_51', 'In the event that this occurs', 'Bu gerçekleşirse', 'In the event that this occurs, measures will be taken.', 'B2', 22, 51, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_52', 'This plays a crucial role in', 'Bu, ... içinde kritik bir rol oynar', 'This plays a crucial role in decision-making.', 'B2', 22, 52, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_53', 'This is a prerequisite for', 'Bu, ... için ön koşuldur', 'This is a prerequisite for long-term success.', 'B2', 22, 53, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_54', 'This serves the purpose of', 'Bu, ... amacına hizmet eder', 'This serves the purpose of improving access.', 'B2', 22, 54, '2026-06-11 13:02:44.865252+00');
