INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_56', 'This condition allows for', 'Bu koşul ...''a olanak sağlar', 'This condition allows for flexibility.', 'B2', 22, 56, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_57', 'This increases the likelihood that', 'Bu, ... olasılığını artırır', 'This increases the likelihood that goals are met.', 'B2', 22, 57, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_58', 'This depends on whether', 'Bu, ... olup olmamasına bağlıdır', 'This depends on whether support is provided.', 'B2', 22, 58, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_59', 'This creates an opportunity to', 'Bu, ... için bir fırsat yaratır', 'This creates an opportunity to innovate.', 'B2', 22, 59, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_6', 'This approach tends to', 'Bu yaklaşım genellikle ... eğilimindedir', 'This approach tends to overlook social factors.', 'B2', 22, 6, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_60', 'This remains possible only if', 'Bu, ancak ... ise mümkün olur', 'This remains possible only if resources are available.', 'B2', 22, 60, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_61', 'Taking all factors into account', 'Tüm faktörleri göz önünde bulundurarak', 'Taking all factors into account, change is necessary.', 'B2', 22, 61, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_62', 'This highlights the fact that', 'Bu, şu gerçeği vurgular:', 'This highlights the fact that inequality persists.', 'B2', 22, 62, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_63', 'It can therefore be concluded that', 'Dolayısıyla şu sonuca varılabilir ki', 'It can therefore be concluded that reform is urgent.', 'B2', 22, 63, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_64', 'This ultimately leads to', 'Bu nihayetinde ...''e yol açar', 'This ultimately leads to systemic change.', 'B2', 22, 64, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_65', 'The findings indicate that', 'Bulgular, ... olduğunu gösteriyor', 'The findings indicate that progress is uneven.', 'B2', 22, 65, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_66', 'This reinforces the idea that', 'Bu, ... fikrini güçlendirir', 'This reinforces the idea that planning matters.', 'B2', 22, 66, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_67', 'At the same time', 'Aynı zamanda', 'At the same time, risks must be managed.', 'B2', 22, 67, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_68', 'This calls into question whether', '... olup olmadığını sorgulatır', 'This calls into question whether the strategy works.', 'B2', 22, 68, '2026-06-11 13:02:44.865252+00');
