INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_70', 'This demonstrates how', 'Bu, ... nasıl olduğunu gösterir', 'This demonstrates how systems adapt.', 'B2', 22, 70, '2026-06-11 13:02:44.865252+00');
