INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_72', 'This marks a significant shift in', 'Bu, ... alanında önemli bir değişimi işaret eder', 'This marks a significant shift in policy.', 'B2', 22, 72, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_73', 'Overall, it appears that', 'Genel olarak, ... gibi görünüyor', 'Overall, it appears that progress is slow.', 'B2', 22, 73, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_74', 'This serves as an example of', 'Bu, ... için bir örnek teşkil eder', 'This serves as an example of effective planning.', 'B2', 22, 74, '2026-06-11 13:02:44.865252+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('B2_22_75', 'This underscores the importance of', 'Bu, ...''in önemini vurgular', 'This underscores the importance of transparency.', 'B2', 22, 75, '2026-06-11 13:02:44.865252+00');
