INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_20', 'this deserves closer scrutiny', 'bu daha yakından incelenmeyi hak ediyor', 'This deserves closer scrutiny before approval.', 'C1', 18, 20, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_21', 'I partially agree with the view that', 'şu görüşe kısmen katılıyorum', 'I partially agree with the view that reform is needed.', 'C1', 18, 21, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_22', 'I see where you are coming from', 'seni anlıyorum', 'I see where you are coming from, but I disagree.', 'C1', 18, 22, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_23', 'that may be true to some extent', 'bu bir ölçüde doğru olabilir', 'That may be true to some extent, but not entirely.', 'C1', 18, 23, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_24', 'I take issue with the claim that', 'şu iddiaya itiraz ediyorum', 'I take issue with the claim that results are neutral.', 'C1', 18, 24, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_25', 'I would push back against the idea that', 'şu fikre karşı dururum', 'I would push back against the idea that this is final.', 'C1', 18, 25, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_26', 'there is some merit in saying that', 'bunu söylemenin bir değeri var', 'There is some merit in saying that experience matters.', 'C1', 18, 26, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_27', 'I respectfully disagree with', 'saygıyla katılmıyorum', 'I respectfully disagree with that conclusion.', 'C1', 18, 27, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_28', 'I am torn between two views', 'iki görüş arasında kaldım', 'I am torn between two views on regulation.', 'C1', 18, 28, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_29', 'that argument fails to consider', 'o argüman şunu dikkate almıyor', 'That argument fails to consider long-term effects.', 'C1', 18, 29, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_3', 'I find it hard to accept that', 'şunu kabul etmekte zorlanıyorum', 'I find it hard to accept that this was unavoidable.', 'C1', 18, 3, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_30', 'I acknowledge the point about', 'şu noktayı kabul ediyorum', 'I acknowledge the point about efficiency.', 'C1', 18, 30, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_31', 'I would nuance that by saying', 'bunu şöyle yumuşatırım', 'I would nuance that by saying context matters.', 'C1', 18, 31, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_32', 'I am sceptical about the claim that', 'şu iddiaya şüpheyle yaklaşıyorum', 'I am sceptical about the claim that prices will fall.', 'C1', 18, 32, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_33', 'there is room for disagreement here', 'burada görüş ayrılığına yer var', 'There is room for disagreement here.', 'C1', 18, 33, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_34', 'I do not share the assumption that', 'şu varsayımı paylaşmıyorum', 'I do not share the assumption that growth is endless.', 'C1', 18, 34, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_35', 'that interpretation seems overstated', 'o yorum abartılı görünüyor', 'That interpretation seems overstated to me.', 'C1', 18, 35, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_36', 'I see this somewhat differently', 'bunu biraz farklı görüyorum', 'I see this somewhat differently from you.', 'C1', 18, 36, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_37', 'there is a counterargument to be made', 'karşı bir argüman da var', 'There is a counterargument to be made here.', 'C1', 18, 37, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_38', 'I remain open to the possibility that', 'şu olasılığa açığım', 'I remain open to the possibility that conditions change.', 'C1', 18, 38, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_39', 'that conclusion does not fully follow', 'o sonuç tam olarak çıkmıyor', 'That conclusion does not fully follow from the data.', 'C1', 18, 39, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_4', 'there is a strong case for', 'güçlü bir gerekçe var', 'There is a strong case for changing the policy.', 'C1', 18, 4, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_40', 'I would not go so far as to say that', 'şunu diyecek kadar ileri gitmem', 'I would not go so far as to say that it failed.', 'C1', 18, 40, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_41', 'to put it another way', 'başka bir deyişle', 'To put it another way, we need more time.', 'C1', 18, 41, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_43', 'let me be clear about this', 'bu konuda net olayım', 'Let me be clear about this from the start.', 'C1', 18, 43, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_44', 'the key point here is', 'buradaki kilit nokta', 'The key point here is accountability.', 'C1', 18, 44, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_45', 'this brings me to my next point', 'bu beni bir sonraki noktaya getiriyor', 'This brings me to my next point.', 'C1', 18, 45, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_46', 'to a large extent', 'büyük ölçüde', 'To a large extent, success depends on trust.', 'C1', 18, 46, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_47', 'that said', 'bununla birlikte', 'That said, risks remain.', 'C1', 18, 47, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_48', 'in practical terms', 'pratik açıdan', 'In practical terms, this is costly.', 'C1', 18, 48, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_49', 'for the sake of argument', 'varsayım olarak', 'For the sake of argument, let us agree.', 'C1', 18, 49, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_5', 'I am inclined to think that', 'şöyle düşünmeye meyilliyim', 'I am inclined to think that timing matters.', 'C1', 18, 5, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_50', 'what matters most is', 'en önemli olan şey', 'What matters most is implementation.', 'C1', 18, 50, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_51', 'this is where the difficulty lies', 'zorluk burada yatıyor', 'This is where the difficulty lies.', 'C1', 18, 51, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_52', 'at the heart of the issue is', 'meselenin özünde', 'At the heart of the issue is trust.', 'C1', 18, 52, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_53', 'I would like to stress that', 'şunu vurgulamak isterim', 'I would like to stress that time is limited.', 'C1', 18, 53, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_54', 'in the final analysis', 'nihai analizde', 'In the final analysis, values matter.', 'C1', 18, 54, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_55', 'this should be seen in context', 'bu bağlam içinde görülmeli', 'This should be seen in context.', 'C1', 18, 55, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_56', 'one thing leads to another', 'biri diğerini getiriyor', 'One thing leads to another in negotiations.', 'C1', 18, 56, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_57', 'that is not the whole story', 'bu hikâyenin tamamı değil', 'That is not the whole story.', 'C1', 18, 57, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_58', 'as things stand', 'mevcut durumda', 'As things stand, progress is slow.', 'C1', 18, 58, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_59', 'this warrants further discussion', 'bu daha fazla tartışma gerektiriyor', 'This warrants further discussion.', 'C1', 18, 59, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_6', 'one could reasonably argue that', 'makul olarak savunulabilir ki', 'One could reasonably argue that costs will rise.', 'C1', 18, 6, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_60', 'I would frame it as follows', 'bunu şöyle çerçevelerdim', 'I would frame it as follows.', 'C1', 18, 60, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_61', 'I see the logic behind that', 'bunun mantığını görüyorum', 'I see the logic behind that decision.', 'C1', 18, 61, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_62', 'it would be reasonable to assume that', 'şunu varsaymak makul olur', 'It would be reasonable to assume that costs rise.', 'C1', 18, 62, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_63', 'I would urge caution when', 'şu durumda temkin öneririm', 'I would urge caution when drawing conclusions.', 'C1', 18, 63, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_64', 'there is no easy answer to this', 'bunun kolay bir cevabı yok', 'There is no easy answer to this.', 'C1', 18, 64, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_65', 'I appreciate your perspective', 'bakış açını takdir ediyorum', 'I appreciate your perspective on the issue.', 'C1', 18, 65, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_66', 'I am mindful of the fact that', 'şu gerçeğin farkındayım', 'I am mindful of the fact that resources are limited.', 'C1', 18, 66, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_67', 'we should avoid jumping to conclusions', 'aceleci sonuçlardan kaçınmalıyız', 'We should avoid jumping to conclusions.', 'C1', 18, 67, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_68', 'this may not be ideal, but', 'bu ideal olmayabilir ama', 'This may not be ideal, but it is necessary.', 'C1', 18, 68, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_69', 'I would argue for a balanced approach', 'dengeli bir yaklaşımı savunurum', 'I would argue for a balanced approach.', 'C1', 18, 69, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_7', 'it would be misleading to say that', 'şunu söylemek yanıltıcı olur', 'It would be misleading to say that progress is guaranteed.', 'C1', 18, 7, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_70', 'there are trade-offs involved', 'ödünler söz konusu', 'There are trade-offs involved.', 'C1', 18, 70, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_71', 'I would put forward the view that', 'şu görüşü öne sürerim', 'I would put forward the view that regulation helps.', 'C1', 18, 71, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_72', 'I am willing to concede that', 'şunu kabul etmeye hazırım', 'I am willing to concede that mistakes were made.', 'C1', 18, 72, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_73', 'this is easier said than done', 'söylemesi kolay yapması zor', 'This is easier said than done.', 'C1', 18, 73, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_74', 'we need to tread carefully', 'dikkatli ilerlemeliyiz', 'We need to tread carefully here.', 'C1', 18, 74, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_75', 'I am open to reconsidering this', 'bunu yeniden düşünmeye açığım', 'I am open to reconsidering this proposal.', 'C1', 18, 75, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_76', 'that remains to be seen', 'bu henüz belli değil', 'That remains to be seen.', 'C1', 18, 76, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_77', 'I take your point, however', 'dediğini anlıyorum, ancak', 'I take your point, however risks remain.', 'C1', 18, 77, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_78', 'this calls for a measured response', 'bu ölçülü bir yanıt gerektiriyor', 'This calls for a measured response.', 'C1', 18, 78, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_79', 'I would refrain from making assumptions', 'varsayım yapmaktan kaçınırım', 'I would refrain from making assumptions.', 'C1', 18, 79, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_8', 'I remain unconvinced that', 'hâlâ ikna olmuş değilim ki', 'I remain unconvinced that this solution works.', 'C1', 18, 8, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_80', 'we should keep an open mind', 'açık fikirli olmalıyız', 'We should keep an open mind.', 'C1', 18, 80, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_81', 'to sum up my position', 'görüşümü özetlemek gerekirse', 'To sum up my position, change is needed.', 'C1', 18, 81, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_82', 'the bottom line is that', 'sonuç olarak', 'The bottom line is that trust matters.', 'C1', 18, 82, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_83', 'I will leave it at that', 'burada bırakacağım', 'I will leave it at that.', 'C1', 18, 83, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_84', 'this is something we need to revisit', 'bunu yeniden ele almalıyız', 'This is something we need to revisit.', 'C1', 18, 84, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_85', 'I stand by my earlier point', 'önceki noktama katılıyorum', 'I stand by my earlier point.', 'C1', 18, 85, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_86', 'this has broader implications', 'bunun daha geniş etkileri var', 'This has broader implications.', 'C1', 18, 86, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_87', 'I would welcome further input', 'ek görüşleri memnuniyetle karşılarım', 'I would welcome further input.', 'C1', 18, 87, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_88', 'that captures my main concern', 'bu ana endişemi özetliyor', 'That captures my main concern.', 'C1', 18, 88, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_89', 'this deserves serious consideration', 'bu ciddi değerlendirme hak ediyor', 'This deserves serious consideration.', 'C1', 18, 89, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_9', 'from my standpoint', 'benim bakış açımdan', 'From my standpoint, clarity is missing.', 'C1', 18, 9, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_90', 'I will reserve judgment for now', 'şimdilik yargımı saklı tutacağım', 'I will reserve judgment for now.', 'C1', 18, 90, '2026-06-11 13:02:44.90622+00');
INSERT INTO public.dictionary_words (id, english, turkish, example, level, grp, word_order, created_at) VALUES ('C1_18_91', 'this marks a shift in thinking', 'bu düşüncede bir değişimi işaret ediyor', 'This marks a shift in thinking.', 'C1', 18, 91, '2026-06-11 13:02:44.90622+00');
